Evidence C - timeout settings (api/config/production.yaml):
redis:
  connectTimeoutMs: 30000
  commandTimeoutMs: 0           # 0 = wait for the reply forever
http:
  maxInFlightPerInstance: 40    # above that: 503 "server busy" at once
postgres:
  poolSize: 20                  # per instance
  statementTimeoutMs: 300

Proposed fix (PR #918, "make the cache optional"):
  async get(key: string) {
    try {
      const cached = await this.redis.get(key);     // client settings unchanged (C)
      if (cached !== null) return cached;
    } catch {
      // Redis failed: fall through to PostgreSQL
    }
    return this.postgres.load(key);
  }

Statement: "Board question 4: PR #918 is the fix. Once a Redis error falls back to PostgreSQL, the 30 s timeout no longer matters."
